/// Runs one saved configuration from the ordered-operations queue.
#[derive(Clone, Debug, PartialEq, Eq, serde::Deserialize, schemars::JsonSchema, gpui::Action)]
#[action(namespace = groovy_dependencies_panel)]
#[serde(deny_unknown_fields)]
pub struct RunOrderedConfiguration {
    pub worktree_id: usize,
    pub label: String,
    #[serde(default)]
    pub source: Option<String>,
}

#[derive(Clone, Copy, Debug, Default, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum BuildToolView {
    #[default]
    Dependencies,
    Gradle,
    Maven,
}

impl BuildToolView {
    const ALL: [Self; 3] = [Self::Dependencies, Self::Gradle, Self::Maven];

    pub fn label(self) -> &'static str {
        match self {
            Self::Dependencies => "Dependencies",
            Self::Gradle => "Gradle",
            Self::Maven => "Maven",
        }
    }
}

#[derive(Clone, Copy, Default, Eq, PartialEq)]
enum BuildToolControlsLayout {
    #[default]
    Wide,
    Compact,
    Narrow,
}

impl BuildToolControlsLayout {
    fn for_width(width: Pixels, rem_size: Pixels) -> Self {
        if width < rem_size * 8.5 {
            Self::Narrow
        } else if width < rem_size * 16.5 {
            Self::Compact
        } else {
            Self::Wide
        }
    }
}

#[derive(Clone, Copy, Debug, Default, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
enum GraphFactFilter {
    #[default]
    All,
    Direct,
    Conflicts,
    Unavailable,
}

impl GraphFactFilter {
    fn label(self) -> &'static str {
        match self {
            Self::All => "All facts",
            Self::Direct => "Direct dependencies",
            Self::Conflicts => "Conflict resolution",
            Self::Unavailable => "Unavailable metadata",
        }
    }

    fn next(self) -> Self {
        match self {
            Self::All => Self::Direct,
            Self::Direct => Self::Conflicts,
            Self::Conflicts => Self::Unavailable,
            Self::Unavailable => Self::All,
        }
    }
}

#[derive(Clone, Copy, Debug, Default, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
enum GraphFactPresentation {
    #[default]
    Tree,
    Flat,
}

impl GraphFactPresentation {
    fn label(self) -> &'static str {
        match self {
            Self::Tree => "Tree groups",
            Self::Flat => "Flat list",
        }
    }

    fn next(self) -> Self {
        match self {
            Self::Tree => Self::Flat,
            Self::Flat => Self::Tree,
        }
    }
}

#[derive(Clone, Copy, Debug, Default, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum MavenGraphScope {
    #[default]
    All,
    Compile,
    Runtime,
    Test,
    Provided,
    System,
    Import,
    Other,
}

impl MavenGraphScope {
    pub(crate) fn label(self) -> &'static str {
        match self {
            Self::All => "All scopes",
            Self::Compile => "compile",
            Self::Runtime => "runtime",
            Self::Test => "test",
            Self::Provided => "provided",
            Self::System => "system",
            Self::Import => "import",
            Self::Other => "Other or unspecified",
        }
    }

    fn next(self) -> Self {
        match self {
            Self::All => Self::Compile,
            Self::Compile => Self::Runtime,
            Self::Runtime => Self::Test,
            Self::Test => Self::Provided,
            Self::Provided => Self::System,
            Self::System => Self::Import,
            Self::Import => Self::Other,
            Self::Other => Self::All,
        }
    }

    pub(crate) fn matches(self, scope: &str) -> bool {
        match self {
            Self::All => true,
            Self::Other => !matches!(
                scope,
                "compile" | "runtime" | "test" | "provided" | "system" | "import"
            ),
            _ => scope == self.label(),
        }
    }
}

