    async fn exercise_operation_controls(
        project: &Entity<Project>,
        lsp_store: &Entity<project::LspStore>,
        worktree_id: WorktreeId,
        provider: GraphFixtureProvider,
        fs: &Arc<project::FakeFs>,
        commands: &Arc<AtomicUsize>,
        version: &Arc<AtomicUsize>,
        ordered_only: bool,
        cx: &mut TestAppContext,
    ) {
        use project::Fs as _;
        async fn refresh_operations(
            panel: &Entity<DependenciesPanel>,
            lsp_store: &Entity<project::LspStore>,
            worktree_id: WorktreeId,
            provider: GraphFixtureProvider,
            cx: &mut gpui::VisualTestContext,
        ) {
            cx.run_until_parked();
            cx.background_executor
                .timer(std::time::Duration::from_millis(50))
                .await;
            cx.run_until_parked();
            lsp_store.update(cx, |store, cx| store.refresh_jdtls_project(worktree_id, cx));
            cx.executor()
                .advance_clock(std::time::Duration::from_millis(300));
            cx.run_until_parked();
            if provider == GraphFixtureProvider::Gradle {
                lsp_store
                    .update(cx, |store, cx| {
                        store.synchronize_local_gradle_project(Some(worktree_id), cx)
                    })
                    .expect("Explicit synchronization after restored Gradle wrapper");
                cx.executor()
                    .advance_clock(std::time::Duration::from_millis(300));
                cx.run_until_parked();
                lsp_store.update(cx, |store, cx| store.refresh_jdtls_project(worktree_id, cx));
            }
            for _ in 0..40 {
                cx.executor()
                    .advance_clock(std::time::Duration::from_millis(300));
                cx.background_executor
                    .timer(std::time::Duration::from_millis(50))
                    .await;
                cx.run_until_parked();
                panel.update(cx, |panel, cx| panel.rebuild(cx));
                if panel.read_with(cx, |panel, cx| {
                    panel.operation_selections.len() == 2
                        && lsp_store
                            .read(cx)
                            .jdtls_project_snapshot(worktree_id)
                            .is_some_and(|(_, current)| current)
                }) {
                    return;
                }
            }
            panic!(
                "Current operation metadata did not recover: {:?}",
                panel.read_with(cx, |panel, _| panel.host.status().clone())
            );
        }
        let view = if provider == GraphFixtureProvider::Maven {
            BuildToolView::Maven
        } else {
            BuildToolView::Gradle
        };
        let (container, cx) = cx.add_window_view(|window, cx| {
            workspace::MultiWorkspace::test_new(project.clone(), window, cx)
        });
        let workspace = container.read_with(cx, |container, _| container.workspace().clone());
        let events = Arc::new(std::sync::Mutex::new(Vec::new()));
        workspace.update(cx, |workspace, _| {
            workspace.set_terminal_provider(OperationTerminal(events.clone()))
        });
        let async_cx = cx.update(|window, cx| window.to_async(cx));
        let panel = DependenciesPanel::load(workspace.downgrade(), async_cx)
            .await
            .expect("operation panel");
        panel.update(cx, |panel, cx| {
            panel.active = true;
            panel.view = view;
            match view {
                BuildToolView::Maven => panel.preferences.show_maven_toolbar = false,
                BuildToolView::Gradle => panel.preferences.show_gradle_toolbar = false,
                _ => {}
            }
            panel.rebuild(cx);
            panel.host.expand_all();
        });
        workspace.update_in(cx, |workspace, window, cx| {
            workspace.add_panel(panel.clone(), window, cx);
            workspace
                .right_dock()
                .update(cx, |dock, cx| dock.set_open(true, window, cx));
            workspace.focus_panel::<DependenciesPanel>(window, cx);
        });
        let selections = panel.read_with(cx, |panel, _| {
            assert_eq!(panel.operation_selections.len(), 2);
            if provider == GraphFixtureProvider::Maven {
                for id in panel.operation_selections.keys() {
                    let row = panel
                        .host
                        .visible_rows()
                        .iter()
                        .find(|row| &row.id == id)
                        .expect("runnable Maven row");
                    assert!(
                        row.secondary_label
                            .as_deref()
                            .is_some_and(|detail| detail.contains("run offline through Tasks")),
                        "runnable Maven rows should show their execution status"
                    );
                }
            }
            let mut selections = panel
                .operation_selections
                .iter()
                .map(|(id, receipt)| (id.clone(), receipt.clone()))
                .collect::<Vec<_>>();
            selections.sort_by(|left, right| left.0.0.cmp(&right.0.0));
            selections
        });
        cx.update(|window, _| window.activate_a11y_for_test());
        if ordered_only {
            focus_tree_control(cx, "Refresh Dependencies");
            focus_tree_control(cx, "Search dependency tree");
            press_tree_key(cx, "enter");
            assert!(cx.update(|window, cx| {
                panel
                    .read(cx)
                    .graph_search
                    .read(cx)
                    .focus_handle(cx)
                    .is_focused(window)
            }));
            focus_tree_control(cx, "Search dependency tree");
            press_tree_key(cx, "enter");
            cx.update(|window, cx| {
                window.draw(cx).clear(cx);
                let tree: serde_json::Value = serde_json::from_str(
                    &window
                        .debug_a11y_tree_json()
                        .expect("collapsed search and queue"),
                )
                .expect("accessibility JSON");
                let nodes = tree["nodes"].as_object().expect("nodes");
                for label in [
                    "Search admitted dependency graph facts",
                    "Ordered operations (0)",
                    "Run Ordered Operations Offline",
                ] {
                    assert!(!nodes.values().any(|node| node["aria"]["label"] == label));
                }
            });
            invoke_panel_menu_command(cx, "Ordered operations (0)");
            assert!(panel.read_with(cx, |panel, _| panel.preferences.ordered_operations_expanded));
            let add_order = |cx: &mut gpui::VisualTestContext| {
                for index in [1, 0, 1] {
                    let (id, _) = selections
                        .get(index)
                        .expect("two current typed operation rows");
                    panel.update(cx, |panel, cx| {
                        panel.host.select(id.clone());
                        cx.notify();
                    });
                    invoke_selected_row_command(&panel, cx, "Add to Queue");
                }
            };
            panel.update_in(cx, |panel, window, cx| {
                panel.run_ordered_offline_operations(window, cx)
            });
            cx.run_until_parked();
            assert!(events.lock().expect("events").is_empty());
            add_order(cx);
            panel.update(cx, |panel, cx| {
                panel.set_ordered_operations_expanded(false, cx)
            });
            panel.update(cx, |panel, cx| panel.rebuild(cx));
            panel.read_with(cx, |panel, _| {
                assert!(!panel.preferences.ordered_operations_expanded);
                assert!(!panel.host.expanded().contains(&ordered_operation_root_id()));
                assert_eq!(panel.ordered_operations.len(), 3);
            });
            invoke_panel_menu_command(cx, "Ordered operations (3)");
            let workspace_windows = cx.read(|cx| cx.windows());
            for (mode, use_keyboard) in [("Float", true), ("Open in Window", false)] {
                panel.update(cx, |panel, cx| {
                    panel.set_ordered_operations_expanded(false, cx)
                });
                invoke_panel_menu_command(cx, mode);
                let detached_window = cx
                    .read(|cx| cx.windows())
                    .into_iter()
                    .find(|window| !workspace_windows.contains(window))
                    .expect("detached build tool window");
                let mut detached = gpui::VisualTestContext::from_window(detached_window, cx);
                detached.update(|window, cx| {
                    window.activate_a11y_for_test();
                    window.draw(cx).clear(cx);
                });
                if use_keyboard {
                    invoke_panel_menu_command(&mut detached, "Ordered operations (3)");
                } else {
                    open_panel_menu(&mut detached);
                    let queue_entry = detached
                        .debug_bounds("MENU_ITEM-Ordered operations (3)")
                        .expect("counted queue menu entry");
                    detached.simulate_click(queue_entry.center(), Default::default());
                    detached.run_until_parked();
                }
                panel.read_with(&detached, |panel, _| {
                    assert!(panel.preferences.ordered_operations_expanded, "{mode}");
                    assert_eq!(panel.host.selected(), Some(&ordered_operation_root_id()));
                    assert!(panel.host.visible_rows().iter().any(|row| {
                        row.parent_id.as_ref() == Some(&ordered_operation_root_id())
                    }));
                });
                detached.update(|window, cx| {
                    assert!(panel.read(cx).focus_handle.contains_focused(window, cx));
                });
                invoke_panel_menu_command(&mut detached, "Return to Dock");
                assert_eq!(cx.read(|cx| cx.windows()), workspace_windows);
            }
            panel.read_with(cx, |panel, cx| {
                assert_eq!(panel.ordered_operations.len(), 3);
                for (receipt, index) in panel.ordered_operations.iter().zip([1, 0, 1]) {
                    assert_eq!(receipt, &selections.get(index).expect("row").1);
                }
                let receipts = vec![selections.first().expect("current row").1.clone(); 32];
                assert_eq!(
                    panel
                        .current_ordered_operation(&receipts, cx)
                        .expect("32 ordered operations")
                        .operations
                        .len(),
                    32
                );
                let mut too_many = receipts.clone();
                too_many.push(selections.first().expect("row").1.clone());
                assert!(compose_ordered_operations(&too_many).is_err());
                let mut foreign = selections.first().expect("row").1.clone();
                foreign.module_root.path = path(worktree_id, "library").path;
                assert!(
                    compose_ordered_operations(&[
                        receipts.first().expect("first").clone(),
                        foreign
                    ])
                    .is_err()
                );
                let mut wrong_generation = receipts.first().expect("first").clone();
                wrong_generation.generation += 1;
                assert!(
                    compose_ordered_operations(&[
                        receipts.first().expect("first").clone(),
                        wrong_generation
                    ])
                    .is_err()
                );
                let mut mixed = receipts.first().expect("first").clone();
                mixed.operations = if provider == GraphFixtureProvider::Maven {
                    vec![JvmBuildOperation::GradleTask {
                        path: ":application:verify".into(),
                    }]
                } else {
                    vec![JvmBuildOperation::MavenPhase {
                        lifecycle: "default".into(),
                        phase: "verify".into(),
                    }]
                };
                assert!(
                    compose_ordered_operations(&[receipts.first().expect("first").clone(), mixed])
                        .is_err()
                );
                assert!(
                    panel
                        .host
                        .visible_rows()
                        .iter()
                        .any(|row| row.id == ordered_operation_root_id())
                );
            });
            panel.update(cx, |panel, cx| {
                panel.host.select(ordered_operation_root_id());
                panel.host.reveal_selection(ScrollStrategy::Center);
                cx.notify();
            });
            cx.update(|window, cx| {
                panel.read(cx).focus_handle(cx).focus(window, cx);
                window.draw(cx).clear(cx);
            });
            cx.simulate_keystrokes("shift-f10");
            cx.update(|window, cx| {
                let (menu, _, _) = panel
                    .read(cx)
                    .graph_context_menu
                    .as_ref()
                    .expect("queue menu");
                let entries = menu.read(cx).accessibility_contracts();
                assert!(entries.iter().any(|entry| entry.label
                    == "Run Ordered Operations Offline"
                    && !entry.disabled));
                assert!(!entries.iter().any(|entry| entry.label == "Add to Queue"));
                window.draw(cx).clear(cx);
                let cancel = cx
                    .build_action("menu::Cancel", None)
                    .expect("menu cancel action");
                window.dispatch_action(cancel, cx);
            });
            cx.update(|window, cx| {
                assert!(panel.read(cx).focus_handle(cx).is_focused(window));
                assert!(panel.read(cx).graph_context_menu.is_none());
            });
            for _ in 0..2 {
                cx.update(|window, cx| {
                    window.draw(cx).clear(cx);
                    let tree: serde_json::Value =
                        serde_json::from_str(&window.debug_a11y_tree_json().expect("AX"))
                            .expect("AX JSON");
                    let nodes = tree["nodes"].as_object().expect("nodes");
                    assert!(nodes.values().any(|node| {
                        node["aria"]["label"]
                            .as_str()
                            .is_some_and(|label| label.contains("Ordered offline operations (3)"))
                    }));
                    assert!(
                        !nodes
                            .values()
                            .any(|node| node["aria"]["label"] == "Run Ordered Operations Offline")
                    );
                });
            }
            assert!(
                events.lock().expect("events").is_empty(),
                "composition is input state, not execution"
            );
            invoke_selected_row_command(&panel, cx, "Remove Last Ordered Operation");
            assert_eq!(
                panel.read_with(cx, |panel, _| panel.ordered_operations.len()),
                2
            );
            invoke_selected_row_command(&panel, cx, "Clear Ordered Selection");
            assert!(panel.read_with(cx, |panel, _| panel.ordered_operations.is_empty()));
            if provider == GraphFixtureProvider::Gradle {
                panel.update(cx, |panel, cx| {
                    let id = selections
                        .iter()
                        .find(|(_, receipt)| {
                            receipt
                                .operations
                                .first()
                                .and_then(JvmBuildOperation::gradle_task_path)
                                == Some(":application:verify")
                        })
                        .expect("verify task")
                        .0
                        .clone();
                    panel.host.select(id);
                    cx.notify();
                });
                invoke_selected_row_command(&panel, cx, "Task options");
                panel.update_in(cx, |panel, window, cx| {
                    let input = panel.operation_option_editor.clone();
                    input.update(cx, |editor, cx| {
                        editor.set_text(r#"["--init-script=private-canary"]"#, window, cx)
                    });
                    panel.run_selected_offline_operation(window, cx);
                    let error = panel.operation_notice.as_deref().expect("option error");
                    assert!(error.contains("declared option") && !error.contains("private-canary"));
                    input.update(cx, |editor, cx| {
                        editor.set_text(r#"["--probe=false"]"#, window, cx);
                    });
                    panel.run_selected_offline_operation(window, cx);
                    assert!(panel.operation_notice.as_deref().is_some_and(|notice| {
                        notice.contains("Boolean Gradle task options")
                    }));
                    input.update(cx, |editor, cx| {
                        editor.set_text(
                            r#"["--project-dir=literal $ZED_FILE value","--no-probe","--property-switch"]"#,
                            window,
                            cx,
                        )
                    });
                });
                assert!(events.lock().expect("events").is_empty());
            } else {
                panel.update(cx, |panel, cx| {
                    panel
                        .host
                        .select(selections.first().expect("Maven operation").0.clone());
                    cx.notify();
                });
                invoke_selected_row_command(&panel, cx, "Task options");
                panel.update_in(cx, |panel, window, cx| {
                    let input = panel.operation_option_editor.clone();
                    input.update(cx, |editor, cx| {
                        editor.set_text(r#"["-Pci,!private-canary"]"#, window, cx)
                    });
                    panel.run_selected_offline_operation(window, cx);
                    let error = panel.operation_notice.as_deref().expect("profile error");
                    assert!(error.contains("declared") && !error.contains("private-canary"));
                    for (options, expected) in [
                        (
                            r#"["--fail-fast","--fail-at-end"]"#,
                            "Choose one Maven failure policy",
                        ),
                        (
                            r#"["--threads=2","-T3"]"#,
                            "Configure Maven threads only once",
                        ),
                        (
                            r#"["--threads=0"]"#,
                            "Maven thread count must be a positive integer",
                        ),
                        (
                            r#"["--threads=NaNC"]"#,
                            "Maven threads per core must be a positive number",
                        ),
                        (
                            r#"["-N","--non-recursive"]"#,
                            "Configure non-recursive execution only once",
                        ),
                        (r#"["--fail-never"]"#, "Use a declared profile"),
                    ] {
                        input.update(cx, |editor, cx| editor.set_text(options, window, cx));
                        panel.run_selected_offline_operation(window, cx);
                        assert!(
                            panel
                                .operation_notice
                                .as_deref()
                                .is_some_and(|notice| notice.contains(expected))
                        );
                    }
                    input.update(cx, |editor, cx| {
                        editor.set_text(
                            r#"["-Pci","-P!legacy","-DskipTests","-N","-fae","-T2"]"#,
                            window,
                            cx,
                        );
                    });
                });
                assert!(events.lock().expect("events").is_empty());
            }
            add_order(cx);
            let combined = panel.read_with(cx, |panel, cx| {
                if provider == GraphFixtureProvider::Maven {
                    let mut conflicting = panel.ordered_operations.clone();
                    conflicting
                        .last_mut()
                        .expect("queued Maven operation")
                        .maven_options
                        .failure_policy = Some(MavenReactorFailurePolicy::FailFast);
                    let error = compose_ordered_operations(&conflicting)
                        .expect_err("conflicting Maven queue policies");
                    assert_eq!(
                        error.to_string(),
                        "Choose the same Maven options for the entire ordered run"
                    );
                }
                panel
                    .current_ordered_operation(&panel.ordered_operations, cx)
                    .expect("combined receipt")
            });
            let expected = lsp_store.read_with(cx, |store, _| {
                let (snapshot, current) =
                    store.jdtls_project_snapshot(worktree_id).expect("snapshot");
                combined
                    .plan(snapshot, current, util::paths::PathStyle::Unix)
                    .expect("existing plan")
            });
            let held = panel.read_with(cx, |panel, _| panel.ordered_operations.clone());
            let other_view = if view == BuildToolView::Maven {
                BuildToolView::Gradle
            } else {
                BuildToolView::Maven
            };
            for next_view in [other_view, BuildToolView::Dependencies] {
                panel.update_in(cx, |panel, window, cx| {
                    panel.set_view(next_view, window, cx);
                    assert_eq!(
                        panel.ordered_operations, held,
                        "queue survives a view change"
                    );
                    assert!(panel.operation_selections.is_empty());
                    assert!(panel.ordered_queue_menu(cx).run_ordered);
                });
            }
            panel.update(cx, |panel, cx| {
                panel.host.select(ordered_operation_root_id());
                cx.notify();
            });
            invoke_selected_row_command(&panel, cx, "Run Ordered Operations Offline");
            {
                let events = events.lock().expect("events");
                assert_eq!(events.len(), 1);
                let task = events.first().expect("one shared Tasks invocation");
                assert_eq!(task.literal_prefix_args, task.args.len());
                if provider == GraphFixtureProvider::Gradle {
                    assert_eq!(
                        task.args.get(..5).expect("Gradle invocation options"),
                        [
                            "--offline",
                            "--no-parallel",
                            "--max-workers=3",
                            "--parallel",
                            "--"
                        ]
                    );
                    assert_eq!(task.args.get(4..), expected.template.args.get(1..));
                    assert!(task.args.windows(4).any(|arguments| arguments
                        == [
                            ":application:verify",
                            "--project-dir=literal $ZED_FILE value",
                            "--no-probe",
                            "--property-switch"
                        ]));
                } else {
                    assert_eq!(task.args, expected.template.args);
                    assert_eq!(
                        task.args.get(3..10).expect("Maven arguments"),
                        [
                            "--activate-profiles",
                            "ci,!legacy",
                            "-DskipTests",
                            "--non-recursive",
                            "--fail-at-end",
                            "--threads",
                            "2",
                        ]
                    );
                }
            }
            if provider == GraphFixtureProvider::Gradle {
                fs.insert_file("/groovy-graph/application/Late.kt", b"class Late".to_vec())
                    .await;
                let languages = project.read_with(cx, |project, _| project.languages().clone());
                languages.add(Arc::new(Language::new(
                    LanguageConfig {
                        name: "Kotlin".into(),
                        matcher: LanguageMatcher {
                            path_suffixes: vec!["kt".into()],
                            ..Default::default()
                        }
                        .into(),
                        ..Default::default()
                    },
                    None,
                )));
                let mut kotlin_servers = languages.register_fake_lsp(
                    "Kotlin",
                    FakeLspAdapter {
                        name: "kotlin-lsp",
                        ..FakeLspAdapter::default()
                    },
                );
                let _kotlin_buffer = project
                    .update(cx, |project, cx| {
                        project.open_local_buffer_with_lsp("/groovy-graph/application/Late.kt", cx)
                    })
                    .await
                    .expect("start Kotlin after queuing Gradle Tasks");
                let _kotlin_server = kotlin_servers.next().await.expect("late Kotlin provider");
                cx.run_until_parked();
                panel.read_with(cx, |panel, cx| {
                    assert_eq!(
                        panel.ordered_operations, held,
                        "Kotlin startup keeps the Java-owned queue"
                    );
                    assert!(panel.ordered_queue_menu(cx).run_ordered);
                });
            }
            lsp_store.update(cx, |store, cx| store.refresh_jdtls_project(worktree_id, cx));
            panel.update_in(cx, |panel, window, cx| {
                panel.rebuild(cx);
                assert!(panel.ordered_operations.is_empty());
                assert!(
                    panel
                        .operation_notice
                        .as_deref()
                        .is_some_and(|notice| notice.contains("cleared"))
                );
                panel.ordered_operations = held;
                panel.run_ordered_offline_operations(window, cx);
            });
            cx.run_until_parked();
            assert_eq!(events.lock().expect("events").len(), 1);
            cx.executor()
                .advance_clock(std::time::Duration::from_millis(300));
            cx.run_until_parked();
            panel.update_in(cx, |panel, window, cx| {
                panel.set_view(view, window, cx);
                panel.host.expand_all();
                assert!(panel.ordered_operations.is_empty());
            });
            add_order(cx);
            let wrapper = if provider == GraphFixtureProvider::Maven {
                "/groovy-graph/mvnw"
            } else {
                "/groovy-graph/gradlew"
            };
            fs.remove_file(std::path::Path::new(wrapper), Default::default())
                .await
                .expect("remove owned wrapper");
            cx.run_until_parked();
            panel.update_in(cx, |panel, window, cx| {
                panel.run_ordered_offline_operations(window, cx)
            });
            cx.run_until_parked();
            assert_eq!(events.lock().expect("events").len(), 1);
            fs.insert_file(wrapper, b"#!/bin/sh".to_vec()).await;
            cx.run_until_parked();
            panel.update(cx, |panel, cx| {
                panel.clear_ordered_operations(cx);
                panel.host.expand_all();
            });
            refresh_operations(&panel, lsp_store, worktree_id, provider, cx).await;
            panel.update(cx, |panel, _| panel.host.expand_all());
            add_order(cx);
            assert_eq!(
                panel.read_with(cx, |panel, _| panel.ordered_operations.len()),
                3
            );
            panel.update(cx, |panel, cx| {
                panel.host.select(ordered_operation_root_id());
                cx.notify();
            });
            invoke_selected_row_command(&panel, cx, "Run Ordered Operations Offline");
            assert_eq!(
                events.lock().expect("events").len(),
                2,
                "Recovered ordered run: {:?}",
                panel.read_with(cx, |panel, _| panel.operation_notice.clone())
            );
            let store = project.read_with(cx, |project, _| project.worktree_store());
            let trust = cx.read(|cx| TrustedWorktrees::try_get_global(cx).expect("trust"));
            trust.update(cx, |trust, cx| {
                trust.restrict(
                    store.downgrade(),
                    HashSet::from_iter([PathTrust::Worktree(worktree_id)]),
                    cx,
                )
            });
            cx.run_until_parked();
            panel.update_in(cx, |panel, window, cx| {
                panel.rebuild(cx);
                assert!(panel.ordered_operations.is_empty());
                panel.run_ordered_offline_operations(window, cx);
            });
            cx.run_until_parked();
            assert_eq!(events.lock().expect("events").len(), 2);
            assert_eq!(
                commands.load(Ordering::SeqCst),
                0,
                "all execution uses existing Tasks"
            );
            return;
        }
        for (id, receipt) in &selections {
            panel.update(cx, |panel, cx| {
                panel.host.expand_all();
                panel.host.select(id.clone());
                assert_eq!(panel.host.selected(), Some(id));
                cx.notify();
            });
            invoke_selected_row_command(&panel, cx, "Run offline through Tasks");
            let plan = lsp_store.read_with(cx, |store, _| {
                let (snapshot, current) =
                    store.jdtls_project_snapshot(worktree_id).expect("snapshot");
                receipt
                    .plan(snapshot, current, util::paths::PathStyle::Unix)
                    .expect("current expected plan")
            });
            let events = events.lock().expect("events");
            let task = events.last().expect("existing Tasks terminal event");
            assert_eq!(task.args, plan.template.args);
            assert_eq!(task.literal_prefix_args, task.args.len());
            assert_eq!(
                task.command.as_deref(),
                Some(if provider == GraphFixtureProvider::Maven {
                    "/groovy-graph/mvnw"
                } else {
                    "/groovy-graph/gradlew"
                })
            );
        }
        assert_eq!(events.lock().expect("events").len(), 2);
        assert_eq!(
            commands.load(Ordering::SeqCst),
            0,
            "Run uses Tasks, never a provider execution/graph engine"
        );
        panel.read_with(cx, |panel, _| {
            assert!(
                panel
                    .operation_notice
                    .as_deref()
                    .is_some_and(|notice| notice.contains("sent to Tasks"))
            )
        });
        let mut invalid = selections[0].1.clone();
        invalid.generation += 1;
        panel.update_in(cx, |panel, window, cx| {
            panel
                .operation_selections
                .insert(selections[0].0.clone(), invalid);
            panel.host.select(selections[0].0.clone());
            panel.run_selected_offline_operation(window, cx);
        });
        cx.run_until_parked();
        assert_eq!(events.lock().expect("events").len(), 2);
        panel.read_with(cx, |panel, _| {
            let error = panel.operation_notice.as_deref().expect("stale error");
            assert!(error.contains("refresh"));
            assert!(!error.contains("private-canary") && !error.contains("groovy-graph"));
        });
        lsp_store.update(cx, |store, cx| store.refresh_jdtls_project(worktree_id, cx));
        panel.update_in(cx, |panel, window, cx| {
            panel.rebuild(cx);
            assert!(panel.operation_selections.is_empty());
            panel.run_selected_offline_operation(window, cx);
        });
        assert_eq!(events.lock().expect("events").len(), 2);
        cx.executor()
            .advance_clock(std::time::Duration::from_millis(300));
        cx.run_until_parked();
        panel.update(cx, |panel, cx| {
            panel.rebuild(cx);
            panel.host.expand_all();
            assert_eq!(panel.operation_selections.len(), 2);
            panel.host.select(selections[0].0.clone());
        });
        let wrapper = if provider == GraphFixtureProvider::Maven {
            "/groovy-graph/mvnw"
        } else {
            "/groovy-graph/gradlew"
        };
        fs.remove_file(std::path::Path::new(wrapper), Default::default())
            .await
            .expect("remove disposable wrapper");
        cx.run_until_parked();
        panel.update_in(cx, |panel, window, cx| {
            panel.run_selected_offline_operation(window, cx)
        });
        cx.run_until_parked();
        assert_eq!(events.lock().expect("events").len(), 2);
        panel.read_with(cx, |panel, _| {
            assert!(
                panel.operation_selections.is_empty(),
                "Wrapper removal invalidates provider data"
            );
            assert!(
                panel
                    .operation_notice
                    .as_deref()
                    .is_some_and(|notice| notice.contains("refresh")),
                "Stale wrapper data requires refresh: {:?}",
                panel.operation_notice
            )
        });
        fs.insert_file(wrapper, b"#!/bin/sh".to_vec()).await;
        refresh_operations(&panel, lsp_store, worktree_id, provider, cx).await;
        panel.update(cx, |panel, cx| {
            panel.rebuild(cx);
            panel.host.expand_all();
            panel.host.select(selections[0].0.clone());
        });
        invoke_selected_row_command(&panel, cx, "Run offline through Tasks");
        assert_eq!(events.lock().expect("events").len(), 3);
        if provider == GraphFixtureProvider::Maven {
            version.store(2, Ordering::SeqCst);
            lsp_store.update(cx, |store, cx| store.refresh_jdtls_project(worktree_id, cx));
            cx.executor()
                .advance_clock(std::time::Duration::from_millis(300));
            cx.run_until_parked();
            panel.update(cx, |panel, cx| {
                panel.rebuild(cx);
                assert_eq!(panel.operation_selections.len(), 1);
                assert!(panel.operation_selections.values().all(|receipt| matches!(
                    receipt.operations[0],
                    JvmBuildOperation::MavenPhase { .. }
                )));
            });
        }
        let store = project.read_with(cx, |project, _| project.worktree_store());
        let trust = cx.read(|cx| TrustedWorktrees::try_get_global(cx).expect("trust"));
        trust.update(cx, |trust, cx| {
            trust.restrict(
                store.downgrade(),
                HashSet::from_iter([PathTrust::Worktree(worktree_id)]),
                cx,
            )
        });
        cx.run_until_parked();
        panel.update_in(cx, |panel, window, cx| {
            panel.rebuild(cx);
            assert!(panel.operation_selections.is_empty());
            panel.run_selected_offline_operation(window, cx);
        });
        cx.run_until_parked();
        assert_eq!(events.lock().expect("events").len(), 3);
        assert_eq!(commands.load(Ordering::SeqCst), 0);
    }

