    async fn exercise_saved_build_controls(
        project: &Entity<Project>,
        lsp_store: &Entity<project::LspStore>,
        worktree_id: WorktreeId,
        maven: bool,
        failure: &Arc<AtomicBool>,
        mut release: oneshot::Sender<()>,
        cx: &mut TestAppContext,
    ) {
        let (container, cx) = cx.add_window_view(|window, cx| {
            workspace::MultiWorkspace::test_new(project.clone(), window, cx)
        });
        let workspace = container.read_with(cx, |container, _| container.workspace().clone());
        let async_cx = cx.update(|window, cx| window.to_async(cx));
        let panel = DependenciesPanel::load(workspace.downgrade(), async_cx)
            .await
            .expect("build controls panel");
        panel.update(cx, |panel, cx| {
            panel.active = true;
            panel.view = if maven {
                BuildToolView::Maven
            } else {
                BuildToolView::Gradle
            };
            panel.rebuild(cx);
        });
        workspace.update_in(cx, |workspace, window, cx| {
            workspace.add_panel(panel.clone(), window, cx);
            workspace
                .right_dock()
                .update(cx, |dock, cx| dock.set_open(true, window, cx));
            workspace.focus_panel::<DependenciesPanel>(window, cx);
        });
        cx.update(|window, _| window.activate_a11y_for_test());
        let focus_button = |label: &str, cx: &mut gpui::VisualTestContext| {
            let mut focused = false;
            for _ in 0..64 {
                focused = cx.update(|window, cx| {
                    window.draw(cx).clear(cx);
                    let tree: serde_json::Value = serde_json::from_str(
                        &window.debug_a11y_tree_json().expect("build controls"),
                    )
                    .expect("AX JSON");
                    if tree["gpui_focus"]
                        .as_str()
                        .is_some_and(|id| tree["nodes"][id]["aria"]["label"] == label)
                    {
                        true
                    } else {
                        window.focus_next(cx);
                        false
                    }
                });
                if focused {
                    break;
                }
            }
            assert!(focused, "build control receives shared keyboard focus");
        };
        let press_button = |cx: &mut gpui::VisualTestContext| {
            cx.update(|window, cx| {
                let keystroke = gpui::Keystroke::parse("enter").expect("Enter");
                window.dispatch_event(
                    gpui::KeyDownEvent {
                        keystroke: keystroke.clone(),
                        is_held: false,
                        prefer_character_input: false,
                    }
                    .to_platform_input(),
                    cx,
                );
                window.dispatch_event(gpui::KeyUpEvent { keystroke }.to_platform_input(), cx);
            });
            cx.run_until_parked();
        };
        let label = if maven {
            "Apply saved Maven selection"
        } else {
            "Import Gradle selection"
        };
        panel.update(cx, |panel, cx| {
            panel.host.select_first();
            cx.notify();
        });
        invoke_selected_row_command(&panel, cx, label);
        let cancelled_receipt = panel.read_with(cx, |panel, cx| {
            assert!(panel.build_phase_is_pending(cx));
            panel.build_phase_token.expect("owned UI receipt")
        });
        focus_button("Dependency status details", cx);
        press_button(cx);
        settle_tool_menu(cx);
        for _ in 0..2 {
            cx.update(|window, cx| {
                window.draw(cx).clear(cx);
                let tree: serde_json::Value =
                    serde_json::from_str(&window.debug_a11y_tree_json().expect("pending phase"))
                        .expect("AX JSON");
                let status = tree["nodes"]
                    .as_object()
                    .expect("nodes")
                    .values()
                    .find(|node| node["aria"]["label"] == "Selected JVM build import status")
                    .expect("persistent phase status");
                assert_eq!(status["aria"]["role"], "Status");
                assert_eq!(status["aria"]["live"], "Polite");
                assert!(
                    status["aria"]["value"].as_str().is_some_and(
                        |value| value.contains(if maven { "Maven" } else { "Gradle" })
                    )
                );
            });
        }
        press_tree_key(cx, "escape");
        focus_button("Cancel selected import", cx);
        press_button(cx);
        release.cancellation().await;
        assert!(
            release.is_canceled(),
            "UI receipt cancels only its owned provider request"
        );
        panel.read_with(cx, |panel, cx| {
            assert!(!panel.build_phase_is_pending(cx));
            assert!(panel.build_phase_token.is_none());
            assert!(
                panel
                    .build_phase_notice
                    .as_deref()
                    .is_some_and(|notice| notice.contains("cancelled")),
                "owned cancellation status: {:?}",
                panel.build_phase_notice
            );
        });
        let refresh = |cx: &mut TestAppContext| {
            lsp_store.update(cx, |store, cx| store.refresh_jdtls_project(worktree_id, cx));
            cx.executor()
                .advance_clock(std::time::Duration::from_millis(300));
            cx.run_until_parked();
        };
        refresh(cx);
        panel.update_in(cx, |panel, window, cx| {
            panel.apply_saved_build_selection(maven, window, cx)
        });
        cx.run_until_parked();
        refresh(cx);
        panel.read_with(cx, |panel, _| {
            assert!(panel.build_phase_token.is_none());
            assert!(
                panel
                    .build_phase_notice
                    .as_deref()
                    .is_some_and(|notice| notice.contains("completed"))
            );
        });
        let replacement = lsp_store
            .update(cx, |store, cx| {
                if maven {
                    store.apply_saved_local_maven_selection(worktree_id, cx)
                } else {
                    store.import_selected_local_gradle_project(worktree_id, cx)
                }
            })
            .expect("replacement host phase");
        let replacement_token = lsp_store.read_with(cx, |store, _| {
            store
                .jdtls_project_import_token(worktree_id)
                .expect("replacement receipt")
        });
        assert_ne!(replacement_token, cancelled_receipt);
        panel.update(cx, |panel, cx| {
            panel.build_phase_token = Some(cancelled_receipt);
            panel.cancel_selected_import(cx);
            assert!(
                panel
                    .build_phase_notice
                    .as_deref()
                    .is_some_and(|notice| notice.contains("no other phase"))
            );
        });
        assert_eq!(
            lsp_store.read_with(cx, |store, _| store.jdtls_project_import_token(worktree_id)),
            Some(replacement_token),
            "retired UI receipt cannot cancel replacement host work"
        );
        replacement
            .await
            .expect("replacement survives late UI cancellation");
        refresh(cx);
        failure.store(true, Ordering::SeqCst);
        panel.update_in(cx, |panel, window, cx| {
            panel.apply_saved_build_selection(maven, window, cx)
        });
        cx.run_until_parked();
        refresh(cx);
        panel.read_with(cx, |panel, _| {
            assert!(panel.build_phase_token.is_none());
            let notice = panel.build_phase_notice.as_deref().expect("failure status");
            assert!(
                notice.contains("review jvm_builds")
                    && !notice.contains("private-canary")
                    && !notice.contains("secret")
            );
        });
        failure.store(false, Ordering::SeqCst);
        panel.update_in(cx, |panel, window, cx| {
            panel.apply_saved_build_selection(maven, window, cx)
        });
        cx.run_until_parked();
        refresh(cx);
        panel.read_with(cx, |panel, _| {
            assert!(
                panel
                    .build_phase_notice
                    .as_deref()
                    .is_some_and(|notice| notice.contains("completed"))
            )
        });
        let inventory = project.read_with(cx, |project, cx| {
            project
                .task_store()
                .read(cx)
                .task_inventory()
                .cloned()
                .expect("saved Task inventory")
        });
        inventory.update(cx, |inventory, _| {
            inventory
                .update_file_based_tasks(
                    project::task_store::TaskSettingsLocation::Worktree(
                        settings::SettingsLocation {
                            worktree_id,
                            path: RelPath::from_unix_str(".zed").expect("saved Task folder"),
                        },
                    ),
                    Some(
                        r#"[
                    {"label":"prepare-sync","command":"prepare-sync","tags":["before-sync"]},
                    {"label":"finish-sync","command":"finish-sync","tags":["after-sync"]},
                    {"label":"unrelated","command":"unrelated","tags":["before-build"]}
                ]"#,
                    ),
                )
                .expect("sync Task definitions");
        });
        let events = Arc::new(std::sync::Mutex::new(Vec::new()));
        let (before_ready, ready) = oneshot::channel();
        let (release_before, before_released) = oneshot::channel();
        let launch_gate = Arc::new(std::sync::Mutex::new(Some((before_ready, before_released))));
        let outcomes = Arc::new(std::sync::Mutex::new(VecDeque::new()));
        workspace.update(cx, |workspace, _| {
            workspace.set_terminal_provider(SavedConfigurationTerminal {
                terminal: OperationTerminal(events.clone()),
                launch_gate: launch_gate.clone(),
                outcomes: outcomes.clone(),
            });
        });
        let invoke_sync = |cx: &mut gpui::VisualTestContext| {
            panel.update_in(cx, |panel, window, cx| {
                if maven {
                    panel.reload_maven_projects(window, cx);
                } else {
                    panel.apply_saved_build_selection(false, window, cx);
                }
            });
        };
        let task_labels = || {
            events
                .lock()
                .expect("terminal events")
                .iter()
                .map(|event| event.full_label.clone())
                .collect::<Vec<_>>()
        };
        invoke_sync(cx);
        ready
            .await
            .expect("before-sync Task parked before terminal spawn");
        assert!(lsp_store.read_with(cx, |store, _| {
            store.jdtls_project_import_token(worktree_id).is_none()
        }));
        assert!(task_labels().is_empty());
        invoke_sync(cx);
        release_before.send(()).expect("release before-sync Task");
        cx.run_until_parked();
        refresh(cx);
        assert_eq!(task_labels(), ["prepare-sync", "finish-sync"]);
        panel.read_with(cx, |panel, _| {
            assert!(!panel.build_controls_busy());
            assert!(
                panel
                    .build_phase_notice
                    .as_deref()
                    .is_some_and(|notice| notice.contains("sync hooks completed"))
            );
        });
        events.lock().expect("terminal events").clear();
        lsp_store
            .update(cx, |store, cx| {
                if maven {
                    store.reload_local_maven_projects(worktree_id, cx)
                } else {
                    store.import_selected_local_gradle_project(worktree_id, cx)
                }
            })
            .expect("provider-only import")
            .await
            .expect("reload completed");
        refresh(cx);
        assert!(
            task_labels().is_empty(),
            "provider-only reload cannot run saved hooks"
        );

        outcomes.lock().expect("terminal outcomes").push_back(None);
        invoke_sync(cx);
        cx.run_until_parked();
        assert_eq!(task_labels(), ["prepare-sync"]);
        panel.read_with(cx, |panel, _| {
            assert!(!panel.build_controls_busy());
            assert!(panel.build_phase_notice.as_deref().is_some_and(|notice| {
                notice.contains("before-sync") && notice.contains("cancelled")
            }));
        });

        events.lock().expect("terminal events").clear();
        failure.store(true, Ordering::SeqCst);
        invoke_sync(cx);
        cx.run_until_parked();
        refresh(cx);
        assert_eq!(
            task_labels(),
            ["prepare-sync"],
            "provider failure skips the after-sync Task"
        );
        panel.read_with(cx, |panel, _| {
            assert!(!panel.build_controls_busy());
            let notice = panel
                .build_phase_notice
                .as_deref()
                .expect("import failure notice");
            assert!(notice.contains("did not complete") && !notice.contains("secret"));
        });
        failure.store(false, Ordering::SeqCst);
        events.lock().expect("terminal events").clear();
        invoke_sync(cx);
        cx.run_until_parked();
        refresh(cx);
        assert_eq!(task_labels(), ["prepare-sync", "finish-sync"]);
        assert!(!lsp_store.read_with(cx, |store, _| {
            store.jvm_trigger_is_armed(worktree_id, JvmTaskTrigger::BeforeSync)
        }));
        events.lock().expect("terminal events").clear();
        let (late_ready, ready) = oneshot::channel();
        let (release_late, late_released) = oneshot::channel();
        *launch_gate.lock().expect("terminal gate") = Some((late_ready, late_released));
        invoke_sync(cx);
        ready
            .await
            .expect("before-sync Task awaiting final trust check");
        let worktrees = project.read_with(cx, |project, _| project.worktree_store());
        cx.update(|_, cx| TrustedWorktrees::try_get_global(cx).expect("trust owner"))
            .update(cx, |trusted, cx| {
                trusted.restrict(
                    worktrees.downgrade(),
                    HashSet::from_iter([PathTrust::Worktree(worktree_id)]),
                    cx,
                )
            });
        cx.run_until_parked();
        release_late
            .send(())
            .expect("release Task after trust changes");
        cx.run_until_parked();
        assert!(
            task_labels().is_empty(),
            "revoked trust prevents terminal dispatch"
        );
        assert!(!lsp_store.read_with(cx, |store, _| {
            store.jvm_trigger_is_armed(worktree_id, JvmTaskTrigger::BeforeSync)
        }));
        inventory.update(cx, |inventory, _| {
            inventory
                .update_file_based_tasks(
                    project::task_store::TaskSettingsLocation::Worktree(
                        settings::SettingsLocation {
                            worktree_id,
                            path: RelPath::from_unix_str(".zed").expect("saved Task folder"),
                        },
                    ),
                    None,
                )
                .expect("remove sync Task definitions");
        });
        panel.update_in(cx, |panel, window, cx| {
            panel.apply_saved_build_selection(maven, window, cx);
            assert!(panel.build_phase_token.is_none());
            assert!(
                panel
                    .build_phase_notice
                    .as_deref()
                    .is_some_and(|notice| notice.contains("Trust the project"))
            );
        });
    }

