    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum ScopedGradleDefaultCase {
        Supported,
        Empty,
        Duplicate,
        Overlap,
        Foreign,
        Private,
        Partial,
        WrongAuthority,
        UnmatchedIgnore,
        OutsideActive,
        MissingDefault,
        MissingPolicy,
        FailureOnce,
    }

    impl gpui::Global for ScopedGradleDefaultCase {}

